import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java Main <https-url> [expected-sha256]");
            return;
        }

        Path tempFile = null;
        Scanner scanner = new Scanner(System.in);
        try {
            URL url = new URL(args[0]);
            if (!"https".equalsIgnoreCase(url.getProtocol())) {
                throw new IllegalArgumentException("Only HTTPS URLs are permitted.");
            }

            tempFile = Files.createTempFile("download-", ".exe");
            try (InputStream in = url.openStream()) {
                Files.copy(in, tempFile, StandardCopyOption.REPLACE_EXISTING);
            }

            if (args.length >= 2) {
                String expected = args[1].trim().toLowerCase();
                String actual = sha256(tempFile);
                if (!expected.equals(actual)) {
                    throw new SecurityException("SHA-256 verification failed. Expected: " + expected + ", actual: " + actual);
                }
            }

            System.out.print("Execute downloaded EXE? (type YES to confirm): ");
            if (!scanner.hasNextLine()) {
                System.out.println("No interactive input; execution cancelled.");
                return;
            }
            String answer = scanner.nextLine().trim();
            if (!"YES".equals(answer)) {
                System.out.println("Execution cancelled.");
                return;
            }

            ProcessBuilder builder = new ProcessBuilder(tempFile.toAbsolutePath().toString());
            builder.inheritIO();
            Process process = builder.start();
            int exitCode = process.waitFor();
            System.out.println("Process exited with code: " + exitCode);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        } finally {
            if (tempFile != null) {
                try {
                    Files.deleteIfExists(tempFile);
                } catch (IOException ignored) {
                }
            }
        }
    }

    private static String sha256(Path path) throws NoSuchAlgorithmException, IOException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[8192];
        try (InputStream in = Files.newInputStream(path)) {
            int read;
            while ((read = in.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
        }
        StringBuilder hex = new StringBuilder();
        for (byte b : digest.digest()) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }
}

